# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KUVÂ-YI MİLLÎYE RUHU VE OLUŞUM SÜRECİ</text>\n  <rect x="35" y="55" width="305" height="185" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="187" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Ortaya Çıkış Nedenleri</text>\n  <text x="55" y="108" font-size="11.5" fill="#334155">• Mondros sonrası Anadolu\'nun haksız işgali</text>\n  <text x="55" y="132" font-size="11.5" fill="#334155">• Osmanlı ordusunun terhis edilmesi ve silahların</text>\n  <text x="65" y="150" font-size="11" fill="#475569">elinden alınması (savunmasız kalma)</text>\n  <text x="55" y="176" font-size="11.5" fill="#334155">• İstanbul Hükûmeti\'nin işgallere sessiz ve</text>\n  <text x="65" y="194" font-size="11" fill="#475569">teslimiyetçi kalması</text>\n  <text x="55" y="220" font-size="11.5" font-weight="bold" fill="#991b1b">• Türk milletinin bağımsızlık ve vatan sevgisi</text>\n  <rect x="360" y="55" width="305" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="512" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Özellikleri ve Millî Mücadele\'ye Katkıları</text>\n  <text x="380" y="108" font-size="11.5" fill="#334155">• Bölgesel ve düzensiz halk direniş kuvvetleridir.</text>\n  <text x="380" y="132" font-size="11.5" fill="#334155">• İlk kurşun: Hatay Dörtyol (Güney) ve İzmir (Batı).</text>\n  <text x="380" y="156" font-size="11.5" fill="#334155">• Düzenli ordu kurulana kadar düşmanı oyaladı.</text>\n  <text x="380" y="180" font-size="11.5" fill="#334155">• Azınlık çetelerine karşı halkı korudu, isyanları bastırdı.</text>\n  <text x="380" y="208" font-size="11.5" font-weight="bold" fill="#1e40af">• Ulusal bilinci (millî şuuru) uyandırdı.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MONDROS SONRASI KURULAN CEMİYETLER TABLOSU</text>\n  <rect x="25" y="55" width="210" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="130" y="78" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">Millî (Yararlı) Cemiyetler</text>\n  <text x="38" y="103" font-size="11" fill="#334155">• Trakya-Paşaeli Müd. Hukuk</text>\n  <text x="38" y="123" font-size="11" fill="#334155">• İzmir Müd. Hukuk / Redd-i İlhak</text>\n  <text x="38" y="143" font-size="11" fill="#334155">• Doğu Anadolu Müd. Hukuk</text>\n  <text x="38" y="163" font-size="11" fill="#334155">• Trabzon Muhafaza-i Hukuk</text>\n  <text x="38" y="183" font-size="11" font-weight="bold" fill="#166534">• Kilikyalılar (Çukurova/Adana!)</text>\n  <text x="38" y="203" font-size="11" font-weight="bold" fill="#166534">• Millî Kongre (Basın-yayın, ulusal)</text>\n  <text x="130" y="226" text-anchor="middle" font-size="10.5" fill="#15803d">Sivas Kongresi\'nde birleştirildiler!</text>\n  <rect x="245" y="55" width="210" height="185" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="350" y="78" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#b91c1c">Azınlıkların Zararlı Cemiyetleri</text>\n  <text x="258" y="105" font-size="11" fill="#334155">• Mavri Mira (Rum - Bizans hayali)</text>\n  <text x="258" y="128" font-size="11" fill="#334155">• Etnik-i Eterya (Rum)</text>\n  <text x="258" y="151" font-size="11" fill="#334155">• Pontus Rum (Doğu Karadeniz)</text>\n  <text x="258" y="174" font-size="11" fill="#334155">• Hınçak ve Taşnak (Ermeni)</text>\n  <text x="258" y="197" font-size="11" fill="#334155">• Alyans İsrailit ve Makabi (Yahudi)</text>\n  <text x="350" y="224" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#991b1b">Amaç: Bağımsız devlet kurmak</text>\n  <rect x="465" y="55" width="210" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="570" y="78" text-anchor="middle" font-size="12" font-weight="bold" fill="#a16207">Millî Varlığa Düşman Cemiyetler</text>\n  <text x="478" y="105" font-size="11" fill="#334155">• Sulh ve Selamet-i Osmaniye</text>\n  <text x="478" y="128" font-size="11" fill="#334155">• Teali-i İslam Cemiyeti</text>\n  <text x="478" y="151" font-size="11" fill="#334155">• Kürt Teali Cemiyeti</text>\n  <text x="478" y="174" font-size="11" fill="#334155">• İngiliz Muhipleri (İngiliz mandası)</text>\n  <text x="478" y="197" font-size="11" fill="#334155">• Wilson Prensipleri (ABD mandası)</text>\n  <text x="570" y="224" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#854d0e">Kurtuluşu manda/teslimiyette gördüler</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">MUSTAFA KEMAL PAŞA\'NIN SAMSUN\'A ÇIKIŞI (19 MAYIS 1919)</text>\n  <rect x="35" y="55" width="305" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="187" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Resmî Görevi: 9. Ordu Müfettişliği</text>\n  <text x="55" y="108" font-size="11.5" fill="#334155">• Görünürdeki Görev: Karadeniz\'de güvenliği</text>\n  <text x="65" y="126" font-size="11" fill="#475569">sağlamak, halkın elindeki silahları toplamak.</text>\n  <text x="55" y="152" font-size="11.5" font-weight="bold" fill="#1e40af">• Mustafa Kemal\'in Gerçek Amacı:</text>\n  <text x="65" y="172" font-size="11.5" fill="#334155">Anadolu\'ya geçip millî bilinci uyandırmak,</text>\n  <text x="65" y="192" font-size="11.5" fill="#334155">dağınık direniş güçlerini birleştirerek</text>\n  <text x="65" y="212" font-size="11.5" font-weight="bold" fill="#15803d">tam bağımsızlık mücadelesini başlatmak!</text>\n  <rect x="360" y="55" width="305" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="512" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Samsun Raporu (22 Mayıs 1919)</text>\n  <text x="380" y="110" font-size="11.5" fill="#334155">• Bölgedeki karışıklıklardan Türkler değil,</text>\n  <text x="390" y="128" font-size="11" fill="#475569">Pontus Rum çeteleri sorumludur.</text>\n  <text x="380" y="156" font-size="11.5" fill="#334155">• Rumlar siyasi emellerinden vazgeçerse</text>\n  <text x="390" y="174" font-size="11" fill="#475569">asayiş kendiliğinden düzelecektir.</text>\n  <text x="380" y="202" font-size="11.5" font-weight="bold" fill="#166534">• "Millet, millî hâkimiyet esasını ve Türk</text>\n  <text x="390" y="220" font-size="11.5" font-weight="bold" fill="#166534">milliyetçiliğini kabul etmiştir!"</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
